solid #eaecf0;text-align:left;vertical-align:top}.badge{display:inline-block;padding:6px 9px;border-radius:999px;font-size:12px;font-weight:900}.mapbox{margin-top:8px;border:1px solid #eaecf0;border-radius:14px;overflow:hidden;background:#f8fafc}.mapbox iframe{display:block;width:100%;height:190px;border:0}.maplinks{display:flex;gap:8px;flex-wrap:wrap;margin-top:7px}.productgrid,.couriergrid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.item{border:1px solid #eaecf0;border-radius:18px;padding:14px;background:#fff}.item img{width:100%;height:140px;object-fit:contain;background:#f8fafc;border-radius:12px}.toast{position:fixed;right:18px;bottom:18px;background:#101828;color:#fff;padding:12px 15px;border-radius:12px;display:none;z-index:30}@media(max-width:1000px){.stats{grid-template-columns:repeat(2,1fr)}.grid,.productgrid,.couriergrid{grid-template-columns:1fr}}@media(max-width:700px){.side{width:68px}.brand{font-size:0;text-align:center}.brand:after{content:'🌯';font-size:25px}.nav button{font-size:0;text-align:center}.nav button:first-letter{font-size:20px}.main{margin-left:68px;width:calc(100% - 68px);padding:12px}.top h1{font-size:21px}}
