<div class="app"><aside class="side"><div class="brand">Lavash N1</div><nav class="nav"><button class="active" data-s="home">📊 Dashboard</button><button data-s="orders">📦 Buyurtmalar</button><button data-s="products">🌯 Mahsulotlar</button><button data-s="couriers">🛵 Kuryerlar</button><button data-s="customers">👥 Mijozlar</button><button data-s="settings">⚙️ Sozlamalar</button></nav><button id="logout" class="btn danger" style="width:100%;margin-top:18px">Chiqish</button></aside><main class="main"><div class="top"><div><h1>Lavash N1 boshqaruv markazi</h1><div class="online"><span class="dot"></span>ONLINE • server bilan ulangan</div></div><a href="index.php" class="btn ghost">Sayt ↗</a></div>
<section id="home" class="section active"><div class="stats"><div class="card">📦 Buyurtmalar<div id="morders" class="metric">0</div></div><div class="card">🆕 Yangi<div id="mnew" class="metric">0</div></div><div class="card">📅 Bugun<div id="mtoday" class="metric">0</div></div><div class="card">💰 Tushum<div id="mrev" class="metric">0</div></div><div class="card">🛵 Online kuryer<div id="mcourier" class="metric">0</div></div></div><div class="grid"><div class="card"><h2>Jonli buyurtmalar</h2><div id="liveOrders"></div></div><div class="card"><h2>Do‘kon</h2><div id="store" style="color:#667085">Yuklanmoqda...</div></div></div></section>
<section id="orders" class="section"><div class="card"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px"><button class="btn ghost" onclick="loadOrders()">↻ Yangilash</button><select id="filter" onchange="loadOrders()"><option value="">Barchasi</option><option value="new">Yangi</option><option value="confirmed">Tasdiqlangan</option><option value="preparing">Tayyorlanmoqda</option><option value="delivering">Yetkazilmoqda</option><option value="completed">Yakunlangan</option><option value="cancelled">Bekor</option></select></div><div id="ordersTable" class="tablewrap"></div></div></section>
<section id="products" class="section"><div class="card"><button class="btn primary" onclick="addProduct()">＋ Mahsulot qo‘shish</button><div id="productGrid" class="productgrid" style="margin-top:14px"></div></div></section>
<section id="couriers" class="section"><div class="card"><button class="btn primary" onclick="addCourier()">＋ Kuryer qo‘shish</button><div id="courierGrid" class="couriergrid" style="margin-top:14px"></div></div></section>
<section id="customers" class="section"><div class="card"><h2>Mijozlar</h2><div id="customerTable" class="tablewrap"></div></div></section>
<section id="settings" class="section"><div class="card"><h2>Sozlamalar</h2><form id="settingsForm"><div class="field"><label>Do‘kon nomi</label><input name="store_name"></div><div class="field"><label>Telefon</label><input name="phone"></div><div class="field"><label>Manzil</label><input name="address"></div><div class="field"><label>Dastavka</label><input name="delivery_note"></div><div class="field"><label>Dastavka narxi</label><input name="delivery_fee" type="number"></div><button class="btn primary">Saqlash</button></form></div></section>
</main></div><div id="toast" class="toast"></div>
<script>
const $=s=>document.querySelector(s),api=(a,o={})=>fetch('admin_pro_api.php?action='+a,o).then(async r=>{const d=await r.json().catch(()=>({ok:false,message:'Server javobi noto‘g‘ri'}));return d}),esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function toast(t){const e=$('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',1800)}
function mapHtml(x){const lat=Number(x.lat),lng=Number(x.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng)||!lat||!lng)return '<span style="color:#98a2b3">📍 Lokatsiya tasdiqlanmagan</span>';const q=encodeURIComponent(lat+','+lng);return '<div class="mapbox"><iframe loading="lazy" src="https://maps.google.com/maps?q='+q+'&z=16&output=embed"></iframe></div><div class="maplinks"><a class="btn ghost" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+q+'">📍 Xaritada ochish</a><a class="btn ghost" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+q+'">🧭 Yo‘lni ochish</a></div>'}
async function home(){const d=await api('summary');if(!d.ok)return;const x=d.data;$('#morders').textContent=x.orders;$('#mnew').textContent=x.new;$('#mtoday').textContent=x.today;$('#mrev').textContent=Number(x.revenue).toLocaleString('uz-UZ')+' so‘m';$('#mcourier').textContent=x.online_couriers;const s=await api('settings');if(s.ok)$('#store').innerHTML='<b>'+esc(s.data.store_name)+'</b><br>📞 '+esc(s.data.phone)+'<br>📍 '+esc(s.data.address)+'<br>🚚 '+esc(s.data.delivery_note);const o=await api('orders&status=new');if(o.ok)$('#liveOrders').innerHTML=o.data.slice(0,6).map(x=>'<div style="padding:12px 0;border-bottom:1px solid #eee"><b>#'+x.id+' '+esc(x.customer_name)+'</b> · '+esc(x.phone)+'<br>'+mapHtml(x)+'</div>').join('')||'<span style="color:#667085">Yangi buyurtma yo‘q</span>'}
async function loadOrders(){const d=await api('orders&status='+encodeURIComponent($('#filter').value));if(!d.ok){toast(d.message||'Xato');return}const c=await api('couriers');const couriers=c.ok?c.data:[];$('#ordersTable').innerHTML='<table class="table"><thead><tr><th>#</th><th>Mijoz</th><th>Manzil / Lokatsiya</th><th>Summa</th><th>Kuryer</th><th>Status</th></tr></thead><tbody>'+d.data.map(x=>{const opts=couriers.map(k=>'<option value="'+k.id+'" '+(Number(k.id)===Number(x.courier_id)?'selected':'')+'>'+esc(k.name)+' • '+(k.online?'online':'offline')+'</option>').join('');return '<tr><td>#'+x.id+'<br><small>'+new Date(x.created_at).toLocaleString('uz-UZ')+'</small></td><td><b>'+esc(x.customer_name)+'</b><br>📞 '+esc(x.phone)+'<br><small>'+esc(x.note||'')+'</small></td><td>'+esc(x.address||'')+mapHtml(x)+'</td><td><b>'+Number(x.amount).toLocaleString('uz-UZ')+' so‘m</b><br>'+((x.payment_method||'cash')==='card'?'💳 Karta':'💵 Naqd')+'</td><td><select onchange="assign('+x.id+',this.value)"><option value="">Biriktirilmagan</option>'+opts+'</select></td><td><select onchange="changeStatus('+x.id+',this.value)">'+['new','confirmed','preparing','delivering','completed','cancelled'].map(s=>'<option value="'+s+'" '+(s===x.status?'selected':'')+'>'+s+'</option>').join('')+'</select></td></tr>'}).join('')+'</tbody></table>'}
async function assign(orderId,courierId){if(!courierId)return;const f=new FormData();f.append('order_id',orderId);f.append('courier_id',courierId);const d=await api('assign',{method:'POST',body:f});toast(d.ok?'Kuryerga yuborildi':'Biriktirishda xato');loadOrders()}
async function changeStatus(id,status){const f=new FormData();f.append('id',id);f.append('status',status);const d=await api('status',{method:'POST',body:f});toast(d.ok?'Status saqlandi':'Xato');loadOrders();home()}
async function loadProducts(){const d=await api('products');if(!d.ok)return;$('#productGrid').innerHTML=d.data.map(p=>'<div class="item"><img src="images/'+esc(p.p_image)+'"><h3>'+esc(p.p_title)+'</h3><p style="color:#667085">'+esc(p.p_desc)+'</p><b>'+Number(p.p_prize).toLocaleString('uz-UZ')+' so‘m</b><br><button class="btn ghost" onclick="editProduct('+p.id+')">Tahrirlash</button> <button class="btn danger" onclick="deleteProduct('+p.id+')">O‘chirish</button></div>').join('')}
async function editProduct(id){const d=await api('products');const p=(d.data||[]).find(x=>Number(x.id)===Number(id));if(!p)return;const title=prompt('Mahsulot nomi',p.p_title);if(title===null)return;const price=prompt('Narxi',p.p_prize);if(price===null)return;const f=new FormData();[['id',p.id],['p_title',title],['p_subtitle',p.p_subtitle||''],['p_desc',p.p_desc||'' ],['p_prize',price],['cat_id',p.cat_id],['scat_id',p.scat_id],['p_image',p.p_image],['status',p.status||'show']].forEach(([k,v])=>f.append(k,v));const r=await api('product_save',{method:'POST',body:f});toast(r.ok?'Saqlandi':'Xato');loadProducts()}
async function addProduct(){const title=prompt('Mahsulot nomi');if(title===null)return;const price=prompt('Narxi');if(price===null)return;const f=new FormData();[['id',0],['p_title',title],['p_subtitle',''],['p_desc',''],['p_prize',price],['cat_id','cat-20001'],['scat_id','scat-30001'],['p_image','dish-1.png'],['status','show']].forEach(([k,v])=>f.append(k,v));const r=await api('product_save',{method:'POST',body:f});toast(r.ok?'Qo‘shildi':'Xato');loadProducts()}
async function deleteProduct(id){if(!confirm('Mahsulot o‘chirilsinmi?'))return;const f=new FormData();f.append('id',id);await api('product_delete',{method:'POST',body:f});loadProducts()}
async function loadCouriers(){const d=await api('couriers');if(!d.ok)return;$('#courierGrid').innerHTML=d.data.map(c=>'<div class="item"><h3>'+esc(c.name)+' '+(c.online?'🟢':'⚪')+'</h3><p>'+esc(c.phone)+'</p><p style="color:#667085">'+(c.online?'Online':'Offline')+'</p></div>').join('')}
async function addCourier(){const name=prompt('Kuryer ismi');if(name===null)return;const phone=prompt('Telefon');if(phone===null)return;const pin=prompt('PIN/parol');const f=new FormData();[['id',0],['name',name],['phone',phone],['pin',pin||'']].forEach(([k,v])=>f.append(k,v));const d=await api('courier_save',{method:'POST',body:f});toast(d.ok?'Kuryer qo‘shildi':'Xato');loadCouriers()}
async function loadCustomers(){const d=await api('customers');if(!d.ok)return;$('#customerTable').innerHTML='<table class="table"><thead><tr><th>Ism</th><th>Telefon</th><th>Email</th><th>Buyurtmalar</th><th>Jami</th></tr></thead><tbody>'+d.data.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.phone)+'</td><td>'+esc(x.email||'')+'</td><td>'+x.orders+'</td><td>'+Number(x.spent).toLocaleString('uz-UZ')+' so‘m</td></tr>').join('')+'</tbody></table>'}
async function loadSettings(){const d=await api('settings');if(!d.ok)return;const f=$('#settingsForm');Object.keys(d.data).forEach(k=>{if(f.elements[k])f.elements[k].value=d.data[k]})}
$('#settingsForm').onsubmit=async e=>{e.preventDefault();const d=await api('settings',{method:'POST',body:new FormData(e.target)});toast(d.ok?'Sozlamalar saqlandi':'Xato')};
$('#logout').onclick=async()=>{await api('logout');location.reload()};
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));$('#'+b.dataset.s).classList.add('active');if(b.dataset.s==='orders')loadOrders();if(b.dataset.s==='products')loadProducts();if(b.dataset.s==='couriers')loadCouriers();if(b.dataset.s==='customers')loadCustomers();if(b.dataset.s==='settings')loadSettings()});
home();setInterval(()=>{home();if($('#orders').classList.contains('active'))loadOrders()},6000);
</script></body></html>
